import subprocess
branches=['rachel','monica','phoebe','joey','ross','chandler']
shas={}
for b in branches:
    out=subprocess.check_output(['git','log','origin/friend/'+b,'--format=%H%x00%B%x00%x00']).decode('utf-8',errors='replace')
    for rec in out.split('\x00\x00'):
        if 'Friend-Message: 1' in rec:
            sha=rec.strip().split('\n')[0].strip()
            if len(sha)==40:
                shas[sha]=b
print(len(shas),'unique message commits total')
e05=[s for s in shas if True]
EOF
